requireMFA.cmd:
# Revoke sessions and require MFA re-registration
Revoke-MgUserSignInSession -UserId "{UserPrincipalName}"

# Reset MFA methods
Get-MgUserAuthenticationMethod -UserId "{UserPrincipalName}" | ForEach-Object {
  Remove-MgUserAuthenticationMethod -UserId "{UserPrincipalName}" -AuthenticationMethodId $_.Id -ErrorAction SilentlyContinue
}

syncDevice.cmd:
$device = Get-MgDeviceManagementManagedDevice -Filter "deviceName eq '{DeviceName}'"
if ($device) {
  Sync-MgDeviceManagementManagedDevice -ManagedDeviceId $device.Id
  Write-Host "Sync initiated for $($device.DeviceName)"
} else {
  Write-Host "Device not found"
}

rebootDevice.cmd:
$device = Get-MgDeviceManagementManagedDevice -Filter "deviceName eq '{DeviceName}'"
if ($device) {
  Invoke-MgGraphRequest -Method POST -Uri "https://graph.microsoft.com/v1.0/deviceManagement/managedDevices/$($device.Id)/rebootNow"
  Write-Host "Reboot command sent"
} else {
  Write-Host "Device not found"
}

wipeDevice.cmd:
# WARNING: Factory reset!
$device = Get-MgDeviceManagementManagedDevice -Filter "deviceName eq '{DeviceName}'"
if ($device) {
  $confirm = Read-Host "WIPE $($device.DeviceName)? Type YES"
  if ($confirm -eq "YES") {
    Invoke-MgGraphRequest -Method POST -Uri "https://graph.microsoft.com/v1.0/deviceManagement/managedDevices/$($device.Id)/wipe"
    Write-Host "Wipe sent"
  }
}

retireDevice.cmd:
# Removes company data only
$device = Get-MgDeviceManagementManagedDevice -Filter "deviceName eq '{DeviceName}'"
if ($device) {
  $confirm = Read-Host "RETIRE $($device.DeviceName)? Type YES"
  if ($confirm -eq "YES") {
    Invoke-MgGraphRequest -Method POST -Uri "https://graph.microsoft.com/v1.0/deviceManagement/managedDevices/$($device.Id)/retire"
    Write-Host "Retire sent"
  }
}

